from __future__ import annotations
from typing import Any, Callable


class Field:
    """数据描述符：负责单个字段的存取、默认值与校验。"""

    def __init__(self, *, default: Any = None,
                 validator: Callable[[Any], bool] | None = None) -> None:
        self.default = default
        self.validator = validator
        self.name: str | None = None          # 由 __set_name__ 自动注入

    def __set_name__(self, owner: type, name: str) -> None:
        # 类创建完成后由解释器自动调用，拿到字段名
        self.name = name

    def __get__(self, obj: Any, objtype: type | None = None) -> Any:
        if obj is None:                       # 类访问：返回描述符本身
            return self
        return obj.__dict__.get(self.name, self.default)

    def __set__(self, obj: Any, value: Any) -> None:
        if self.validator and not self.validator(value):
            raise ValueError(f"{self.name} 非法取值: {value!r}")
        obj.__dict__[self.name] = value       # 存进实例字典


class ModelMeta(type):
    """元类：收集命名空间中的 Field，生成 __fields__ 元信息。"""

    def __new__(mcls, name: str, bases: tuple, ns: dict) -> type:
        fields = {k: v for k, v in ns.items() if isinstance(v, Field)}
        # 继承父类字段（子类可覆盖）
        for base in bases:
            fields.update(getattr(base, "__fields__", {}))
        cls = super().__new__(mcls, name, bases, ns)
        cls.__fields__ = fields
        return cls

    def __repr__(cls) -> str:
        cols = ", ".join(f"{n}: {type(f).__name__}" for n, f in cls.__fields__.items())
        return f"<{cls.__name__} ({cols})>"


class Model(metaclass=ModelMeta):
    __fields__: dict[str, Field] = {}

    def __init__(self, **kwargs: Any) -> None:
        for name in self.__fields__:
            if name in kwargs:
                setattr(self, name, kwargs[name])   # 走描述符 __set__，自动校验
        unknown = set(kwargs) - set(self.__fields__)
        if unknown:
            raise TypeError(f"未知字段: {sorted(unknown)}")

    def to_dict(self) -> dict[str, Any]:
        return {n: getattr(self, n) for n in self.__fields__}

    def validate(self) -> list[str]:
        errors = []
        for n, f in self.__fields__.items():
            v = getattr(self, n)
            if f.validator and not f.validator(v):
                errors.append(f"{n}={v!r}")
        return errors

    def __repr__(self) -> str:
        return f"{type(self).__name__}({self.to_dict()})"


# ---- 使用：声明式定义业务模型 ----
class User(Model):
    name = Field(validator=lambda v: isinstance(v, str) and len(v) > 0)
    age = Field(default=0, validator=lambda v: isinstance(v, int) and 0 <= v <= 150)
    email = Field(default="")


if __name__ == "__main__":
    print(ModelMeta.__repr__(User))      # <User (name: Field, age: Field, email: Field)>

    u = User(name="Alice", age=30)
    print(u)                              # User({'name': 'Alice', 'age': 30, 'email': ''})
    print(u.to_dict())

    try:
        User(name="", age=200)            # 校验失败，抛出 ValueError
    except ValueError as e:
        print("校验拦截:", e)

    try:
        User(name="Bob", nickname="b")    # 未知字段，抛出 TypeError
    except TypeError as e:
        print("字段拦截:", e)

