class Cached:
    def __init__(self, func):
        self.func = func
    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        value = self.func(obj)
        obj.__dict__[self.func.__name__] = value
        return value

class Circle:
    def __init__(self, r):
        self.r = r

    @Cached
    def area(self):
        print('computing')
        return 3.14 * self.r ** 2

c = Circle(2)
print(c.area, c.area)
